begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(20);
insert into auth.users(id,email)values('c1000000-0000-4000-8000-000000000001','issue-admin@test.local'),('c1000000-0000-4000-8000-000000000002','issue-manager@test.local'),('c1000000-0000-4000-8000-000000000003','issue-member@test.local'),('c1000000-0000-4000-8000-000000000004','issue-viewer@test.local'),('c1000000-0000-4000-8000-000000000005','issue-out@test.local');insert into profiles(id,email,full_name)select id,email,email from auth.users where id::text like'c1000000-%';
insert into organizations(id,name,created_by)values('c2000000-0000-4000-8000-000000000001','Issue Org','c1000000-0000-4000-8000-000000000001'),('c2000000-0000-4000-8000-000000000002','Other','c1000000-0000-4000-8000-000000000005');insert into organization_members(organization_id,user_id,role,status)values('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','Administrator','Active'),('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000002','Member','Active'),('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000003','Member','Active'),('c2000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000004','Member','Active'),('c2000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000005','Administrator','Active');
