insert into project_members(id,project_id,user_id,access_level)values('c4000000-0000-4000-8000-000000000001','c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000002','Project Manager'),('c4000000-0000-4000-8000-000000000002','c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000003','Project Member'),('c4000000-0000-4000-8000-000000000003','c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000004','Read Only'),('c4000000-0000-4000-8000-000000000004','c3000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000005','Project Manager');
select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select create_project_issue('c3000000-0000-4000-8000-000000000001','Outage','Production is unavailable','Technical','Critical','Customers cannot work','c4000000-0000-4000-8000-000000000002',current_date,current_date,'Restore service',null)$$,'Administrator creates');select is((select status from project_issues),'Open','Initial status trusted');select throws_ok($$insert into project_issues(project_id,title,description,category,severity,current_impact,owner_membership_id,target_resolution_date,resolution_plan,created_by)values('c3000000-0000-4000-8000-000000000001','Direct','D','Scope','Low','I','c4000000-0000-4000-8000-000000000002',current_date,'P','c1000000-0000-4000-8000-000000000001')$$,'42501','permission denied for table project_issues','Direct insert denied');select throws_ok($$delete from project_issues$$,'42501','permission denied for table project_issues','Delete denied');
select lives_ok($$select transition_project_issue_active((select id from project_issues),'In Progress')$$,'Open to progress');select lives_ok($$select transition_project_issue_active((select id from project_issues),'Blocked','Waiting for supplier')$$,'Progress to blocked');select is((select blocked_reason from project_issues),'Waiting for supplier','Reason stored');select throws_ok($$select transition_project_issue_active((select id from project_issues),'Blocked',' ')$$,'22023','A meaningful blocked reason is required.','Blank reason denied');select lives_ok($$select transition_project_issue_active((select id from project_issues),'Blocked','Revised reason')$$,'Blocked reason revised');select lives_ok($$select transition_project_issue_active((select id from project_issues),'Open')$$,'Blocked to open');select is((select blocked_reason from project_issues),null,'Leaving blocked clears reason');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000003',true);select throws_ok($$select update_project_issue((select id from project_issues),'No','D','Scope','Low','I','c4000000-0000-4000-8000-000000000002',current_date,'P')$$,'42501','Issue update is not permitted.','Owner read only');select is((select count(*)from project_issues),1::bigint,'Member reads');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000004',true);select is((select count(*)from project_issues),1::bigint,'Read Only reads');select throws_ok($$select resolve_project_issue((select id from project_issues),'Done')$$,'42501','Issue resolution is not permitted.','Viewer cannot resolve');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000002',true);select lives_ok($$select resolve_project_issue((select id from project_issues),'Service restored')$$,'Manager resolves');select ok((select resolved_by='c1000000-0000-4000-8000-000000000002' and resolved_at is not null from project_issues),'Resolution audit trusted');select throws_ok($$select update_project_issue((select id from project_issues),'No','D','Scope','Low','I','c4000000-0000-4000-8000-000000000002',current_date,'P')$$,'42501','Issue update is not permitted.','Terminal edit denied');select throws_ok($$select cancel_project_issue((select id from project_issues),'Cancel')$$,'42501','Issue cancellation is not permitted.','Resolved cannot cancel');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000005',true);select is((select count(*)from project_issues),0::bigint,'Cross organization read denied');select * from finish();rollback;
